const resend = new Resend('re_xxxxxxxxx');


const { data, error } = await resend.inboxes.agent.update({
inboxId: 'b3e2b2b6-3f0e-4c8e-9ad3-2f43a1e2c7f1',
instructions: 'Answer refund questions yourself. Escalate legal threats.',
